// button passes whatever name the matchup/event data itself carries --
// not always run through this map first. Mirrors the site's own reason
// for NAME_ALIASES existing (see index.html): resolve a known alternate
// spelling to the FIGHTER_STATS key before giving up on it.
function resolveSimName(name) {
  if (FIGHTER_STATS[name]) return name;
  const alias = NAME_ALIASES[String(name || '').trim().toLowerCase()];
  if (alias && FIGHTER_STATS[alias]) return alias;
  return null;
}
function normalizeFighterNameForMatch(name) {
  return String(name == null ? '' : name).trim().toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/ł/g, 'l').replace(/ø/g, 'o').replace(/đ/g, 'd').replace(/ð/g, 'd')
    .replace(/ß/g, 'ss').replace(/æ/g, 'ae').replace(/œ/g, 'oe').replace(/þ/g, 'th');
}
function fighterDivisionRankBadge(name) {
  const key = normalizeFighterNameForMatch(name);
  return key ? (RANKINGS_LOOKUP[key] || '') : '';
}
// Minimal shim for the one field simDivisionFinishPrior() needs from the
