      const yearsAgo = isNaN(d) ? 3 : Math.max(0, (now - d.getTime()) / (1000 * 60 * 60 * 24 * 365.25));
      const weight = 0.5 + 0.5 * Math.max(0, 1 - Math.min(yearsAgo, 6) / 6);
      const isFinish = /^(?:KO|TKO|Submission|Technical Submission)\b/i.test(String(f.method || '').trim());
